.preview-breadcrumb-root { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.preview-breadcrumb-part { display: inline-flex; align-items: center; gap: 8px; min-width: 0; flex: 0 1 auto; }
