.preview-view-actions .preview-icon-action { width: 32px; padding: 5px; }
.preview-source-toggle > svg { flex: none; }
.preview-view-actions button:hover, .preview-view-actions button[aria-pressed="true"] { background: var(--color-background-secondary-ghost-hover); }
.preview-tree-toggle { display: grid; place-items: center; flex: none; width: 32px; height: 32px; margin-left: auto; padding: 0; border: 0; border-radius: 999px; background: transparent; color: var(--color-text-secondary); }
